<?php declare(strict_types=1); ?>
<form class="quote-form" data-product="<?=$e($product['id'])?>" data-variant="<?=$e($variant['id'])?>" data-locale="<?=$lang?>"><fieldset><legend><?=$en?'Check price & availability':'Kiểm tra giá & số suất'?></legend><label><?=$en?'Visit date':'Ngày sử dụng'?><input type="date" name="date" required></label>
<?php if($variant['timeSlots']):?><label><?=$en?'Time slot':'Suất giờ'?><select name="slotId" required><?php if(count($variant['timeSlots'])>1):?><option value=""><?=$en?'Select a time':'Chọn suất giờ'?></option><?php endif;?><?php foreach($variant['timeSlots'] as $slot):?><option value="<?=$e($slot['id'])?>"><?=$e($slot['start'].(isset($slot['end'])?'–'.$slot['end']:''))?></option><?php endforeach;?></select></label><?php endif;?>
